#!/usr/bin/env python3
"""Assemble the independent evidence contract from completed checks."""
import hashlib,json,pathlib,re
E=pathlib.Path(__file__).resolve().parent
R=pathlib.Path('/home/jake/Developer/Course_Academy');J=E.parent
def load(p):return json.loads((E/p).read_text())
def save(p,v):(E/p).write_text(json.dumps(v,indent=2)+'\n')
source=load('source-analysis.json');coverage=load('coverage-results.json')
probes=load('shortcut-results.json')['probes']
keep=[]
for p in probes:
    # Metadata-only source profiles are useful construction coverage, but aren't
    # recognizable learner cues. Retain visible template/shape/name subgroups.
    if p['dataset'] not in ['delivered','batch_delivered'] or p['subgroup'].startswith('profile '):continue
    p=dict(p);ds=p.pop('dataset');p['subgroup']=ds+': '+p['subgroup'];keep.append(p)
keep.append({'cue':'first displayed radio option in completed offline preview','subgroup':'exact five-record batch: two radio preview fixtures','scope':'within_template','strategy':'Choose first displayed option','correct':2,'total':2,'baseline':.2,'disposition':'not_predictive','conclusion':'Both preview fixtures show the correct option first. This is specific to fixture contentIds 3 and 4 with prepublication UUID field IDs; the actual UI hashes task-item and field entity IDs. On accepted records over item IDs 1..128, this strategy succeeds 46/256 versus the 1/5 baseline. The preview coincidence does not demonstrate a delivered fixed-position rule. Future actual DB/task IDs are unavailable.','sample_refs':['render/input.json','render/rendering.json','delivery-batch/accepted.json','shortcut-results.json']})
variation={
 'learner_operation':source['skill'],
 'fixed_features':[
  {'feature':'Already REF integer matrices of the observed small shapes','justification':'The target KP and tutorial define pivots as leading nonzero entries; eliminating a general matrix belongs to later lesson steps. Shape profiles preserve visual workload.'},
  {'feature':'Nonempty pivot set in learner-facing checkbox practice','justification':'All supplied checkbox sources contain pivots and require selecting columns. Excluding the zero matrix keeps this observed response contract; no observed source family is removed.'},
  {'feature':'Complete per-column checkbox bank or five-choice radio bank','justification':'These are the two captured response contracts. Radio ranks 2 and 3 with equally sized candidate subsets give conservative same-method practice; not every mathematically possible rank is needed.'},
  {'feature':'Matrix names tied to source profiles','justification':'A name is irrelevant to pivot membership. Controlled target changes and all visible shape/name cue groups contain differing answers, so no fixed name-to-answer assignment is supported.'}],
 'answer_roles':[
  {'role':'Columns qualifying as pivots','eligible_variation':'Move leading positions while preserving increasing pivots and REF; each column may qualify or fail.','observed':'248 raw samples and 221 delivered samples retain 96 distinct shape/target cases. Leading, trailing, all-column and intermediate decisions occur; all 16 source profiles exercised. One metadata profile collapses to one record after content deduplication because another profile has identical visible wording/shape; the merged visible group remains varied.'},
  {'role':'Number of selected columns','eligible_variation':'Vary nonzero-row count at comparable easy workload.','observed':'Ranks 1,2,3,4 observed in checkbox practice; radio ranks 2 and 3. Exact batch ranks 1,2,3 with five distinct shape/target cases.'},
  {'role':'Radio correct subset and choice position','eligible_variation':'Derive bank and key from current leading positions, vary subset and position independently of matrix coefficients.','observed':'Delivered radio controls have stored correct positions 1..5 with counts 13,7,9,12,16. Actual UI order is separately hashed by item and field IDs; tested hypothetical placements do not fix the correct position.'}],
 'coverage':[
  {'case':'Original source profiles and both response contracts','sample_refs':['source-replays.json','source-replay-results.json'],'result':'16/16 supported practice-source cases replay complete banks, keys, prompts and solutions. Canonical example has no captured answer controls; its displayed matrix is checked separately without claiming a missing bank was captured.'},
  {'case':'Relevant decisions before and after delivery','sample_refs':['independent-samples.json','delivery-independent/accepted.json','coverage-results.json'],'result':'248 -> 221 after 27 content duplicates; all 96 tested shape/target cases remain. Visible shape/name cue groups have multiple targets.'},
  {'case':'Exact runner batch independently assessed','sample_refs':['runner-batch.json','delivery-batch/accepted.json','coverage-results.json','shortcut-results.json'],'result':'All 5 survive, including 3 checkbox and 2 radio records; ranks 1:2, 2:2, 3:1. Constant column 2 answers 2/3 checkbox records, nonzero-column heuristic 0/3, stored positions 3 and 5 answer one radio each. Tiny singleton cue lookups are not claimed to prove a generator-wide rule.'}],
 'counterfactuals':[
  {'kind':'relevant','change':'Checkbox: set first row column 1 from 2 to 0; radio: set second row column 2 from 4 to 0. Keep other entries, seed, profile, response format and radio bank fixed.','expected':'Checkbox pivots change (1,3)->(2,3); radio pivots change (1,2,4)->(1,3,4). Before-response must fail the changed membership while the new response passes.','observed':'Prompts, column vectors, correct keys, named solution columns, solution matrices and rendered summaries change together. Native transferred old checkbox response is rejected on the two changed memberships; old radio subset is rejected. All newly correct choices pass.','status':'passed','justification':'The tutorial defines the first nonzero entry of each nonzero row as its pivot; moving it must move the qualifying column.','sample_refs':['counterfactuals.json','grader-input.json','grader-results.json','render-dependencies/input.json','render-dependencies/rendering.json','render-inspection.json']},
  {'kind':'irrelevant','change':'Change a trailing entry: checkbox row1 col3 -1->8; radio row2 col5 3->-8. Preserve leading entries and bank.','expected':'Same pivot subsets and same accepted learner response, while prompt, vectors and worked-solution matrices show the changed entry.','observed':'Correct subsets preserved; all transferred before-responses accepted by native grader. Rendered summaries retain the same named columns and rendered matrices contain changed entries.','status':'passed','justification':'Entries to the right of a leading nonzero cannot change its position.','sample_refs':['counterfactuals.json','grader-input.json','grader-results.json','render-dependencies/input.json','render-dependencies/rendering.json','render-inspection.json']}],
 'shortcut_probes':keep,
 'delivery':{'stages_examined':['generator explicit rejection and nonempty selection construction','finite structural batch shuffle without replacement','requested difficulty','actual publisher normalization and stable identities','captured inventory and within-batch content deduplication','learner freshness, band weighting, uniform deterministic selection and unconfigured fallback rules','actual UI choice hashing'], 'sample_refs':['packaging-results.json','many-64.json','delivery-batch/delivery.json','delivery-independent/delivery.json','delivery-math-results.json','selection-results.json','shortcut-results.json'], 'result':'No construction rejection removes a valid sampled target: nonempty REF is constructed directly and the policy wrapper preserves valid calls. Delivery retains all five batch records and all 96 tested independent shape/target cases. Read-only selection reproduction reaches every captured or projected candidate with positive easy weight; zero easy weight and no-policy fallback tested explicitly.'},
 'limitations':['Finite samples and prespecified simple strategies cannot certify the absence of all shortcuts.','Captured inventory basis 5362; concurrent publication may change duplicates. No future entity IDs, active policy snapshot or learner history supplied. Selection conclusions are conditional on examined branches; no live learner delivery is claimed.','Canonical source lacks answer-field evidence; its matrix and solution are supported, its missing original control bank cannot be reproduced.','The five stored generated questions have no captured historical generation metadata. Current content was reproduced through published stable identities with controlled seed 0; that seed is not asserted as historical.','The exact batch has singleton visible cue cells. Memorizing an item or post-hoc lookup table is possible in any finite pool; it is not treated as independent evidence of a repeated construction shortcut.']}
save('pedagogical-variation.json',variation)

render=load('render-dependencies/rendering.json');pairs=load('counterfactuals.json');rows=[]
for i,p in enumerate(pairs):
    texts=[re.sub(r'\s+','',render['cases'][2*i+j]['text']) for j in range(2)]
    summaries=[re.search(r'Wecanseethat.*?columns:',t)[0] for t in texts]
    assert (summaries[0]!=summaries[1]) if p['kind']=='relevant' else (summaries[0]==summaries[1])
    assert texts[0]!=texts[1]
    rows.append({'label':p['label'],'rendered_summaries':summaries,'prompt_and_solution_changed':True,'expected_response_relationship_verified':True})
save('render-inspection.json',{'renderer':'unmodified learning UI via render_preview.py','automated_reports':['render/rendering.json','render-dependencies/rendering.json'],'unique_records':15,'screenshots_visually_inspected':['render/question-001.png','render/question-003.png','render/question-005.png','render-dependencies/question-002.png','render-dependencies/question-006.png','render-dependencies/question-009.png'],'observations':'Matrices have correct row/column layout, negative entries and brackets. Checkbox vectors and radio banks display; pivot-column summaries match visible leading entries. Solutions display fully with normal scrolling. No exposed TeX, missing glyphs or clipped answer controls observed. Ordinal suffixes occasionally wrap across lines but remain readable. Completed preview intentionally shows keyed responses; it is not a live unsubmitted learner session.','counterfactual_render_checks':rows})

py=str(R/'.venv/bin/python');env='PYTHONDONTWRITEBYTECODE=1 '
commands=[env+py+' audit.py']
for inp,out in [('runner-batch.json','delivery-batch'),('independent-samples.json','delivery-independent')]:
    commands.append(f'{env}{py} {R}/generate/pipeline/check_delivery.py --input {inp} --source {J}/source/source.json --inventory {J}/source/inventory.json --difficulty easy --output {out} --asset-root {J}/workspace')
commands += ['python3 delivery-verification.py',f'{R}/generate/runs/current/check-engine grader-input.json grader-results.json',f'{env}{py} {R}/generate/pipeline/render_preview.py --input render-records.json --output render --limit 6 --asset-root {J}/workspace',f'{env}{py} {R}/generate/pipeline/render_preview.py --input render-dependency-records.json --output render-dependencies --limit 10 --asset-root {J}/workspace',env+py+' variation-audit.py','python3 finalize-review.py']
save('review-commands.json',{'cwd':str(E),'commands':commands,'derive_dependency_input':'render-dependency-records.json is render-records.json[5:]','notes':'No publication or database commands. All output beneath evidence_root. audit.py disables bytecode writes before importing package files.'})

pkg=J/'workspace';hashes={str(p.relative_to(pkg)):hashlib.sha256(p.read_bytes()).hexdigest() for p in pkg.rglob('*') if p.is_file()}
assert hashes==load('packaging-results.json')['package_before']
save('final-integrity.json',{'package_unchanged':True,'hashes':hashes,'review_binding':{'policy_version':2,'package_hash':'4784074e843aa9cbc0c2bd5f5842fec93987d13d7d61d8bceef2ef87660e2a57','batch_hash':'6b776e7590f0bb16f267d5c6fd45e6c2f4109532f8895de4673ef434de68ab80','source_hash':'c21c28565d96879758f54e97541fa493dd6d40ee5f1334a3d6d2dcec916b8d76','inventory_hash':'66da596a028a0b2e6c273b3e69f92a7383ff4c1b0dce1ae4dd2cacd1ba64013a','engine_hash':'3ff71b034befe7cdf143a5966ba2414f24b22cea78016f9cca37823e58fcc7ec'},'database_writes':0,'published_assets':0,'history_files':'No repair history, preflight, previous review or publication preparation supplied.'})
def check(paths,details):return {'status':'passed','evidence_paths':paths,'details':details}
report={'verdict':'accepted','summary':'No demonstrated defect. All eight checks pass for the captured inventory and tested cases; package unchanged.', 'source_analysis':{k:source[k] for k in ['skill','reasoning_steps','invariants','permitted_variations','source_refs','evidence_paths']},'checks':{
 'source_replay':check(['source-analysis.json','source-replays.json','source-replay-results.json','canonical-matrix.json'],'All 16 captured practice cases replay prompts, solutions, complete banks and keys. Canonical matrix tested separately; original canonical answer controls are absent from source evidence.'),
 'math':check(['audit.py','math-results.json','delivery-verification.py','delivery-math-results.json','inventory-results.json'],'269 listed raw/source/batch cases, four controlled pairs and canonical matrix checked from displayed entries; all 226 delivered keys also independently verified. All 21 captured stored keys are correct.'),
 'variety':check(['independent-samples.json','many-64.json','coverage-results.json','shortcut-results.json'],'All 16 source profiles exercised. 96 distinct tested shape/target decisions survive delivery. Exact batch has five distinct shape/target cases, both response contracts and ranks 1..3; no tested uniform cue answers the batch.'),
 'scope':check(['source-analysis.json','source-replay-results.json','math-results.json','pedagogical-variation.json'],'Already-REF small integer matrices preserve leading-entry recognition and existing checkbox/radio response contracts. Rank and bank extensions use the same method; no row operations or new prerequisite introduced.'),
 'grading':check(['grader-input.json','grader-results.json','counterfactuals.json'],'Real native grade_field: 175 accepted and 203 rejected checks, zero unresolved. Every source/batch option and controlled-pair choice tested, including old-answer transfer and normalized delivered batch. No free-entry fields exist.'),
 'rendering':check(['render/rendering.json','render-dependencies/rendering.json','render-inspection.json','render/question-003.png','render-dependencies/question-006.png'],'15 distinct records rendered through actual UI, including entire batch and all controlled pairs; both reports pass. Representative screenshots inspected for matrices, controls and solutions.'),
 'packaging':check(['packaging-results.json','relocated-records.json','review-commands.json','final-integrity.json'],'Exact Python 3.13.5 matches manifest; standard-library-only dependency map is empty. Rejection boundaries, seeded determinism, exact batch replay and relocation passed. Explicit radio parameter replay preserves content/key but may reorder choices. Package hashes unchanged.'),
 'decision_variation':check(['pedagogical-variation.json','counterfactuals.json','shortcut-results.json','coverage-results.json','delivery-batch/delivery.json','delivery-independent/delivery.json','selection-results.json','inventory-published-results.json','affected-inventory.json'],'Independent role analysis, relevant/irrelevant dependencies and conditional cue probes passed. Actual delivery keeps 5/5 batch records and 221/248 controls without losing any tested shape/target case. Selection rules reproduced read-only across weighted, zero-weight, history and fallback cases; future learner state and IDs remain conditional.')},'findings':[]}
save('result.json',report)
for c in report['checks'].values():
    for path in c['evidence_paths']:assert (E/path).is_file() and (E/path).stat().st_size>0,path
for row in variation['coverage']+variation['counterfactuals']+variation['shortcut_probes']+[variation['delivery']]:
    for path in row['sample_refs']:assert not pathlib.Path(path).is_absolute() and (E/path).is_file() and (E/path).stat().st_size>0,path
(E/'session-state.md').write_text('Review complete. result.json: accepted, eight checks passed, no findings. Source analysis preceded package inspection. Native grader: 175 accepted / 203 rejected / 0 unresolved; delivery: batch 5/5, independent 221/248, all 96 tested shape/target cases retained. Actual UI rendered 15 distinct records; representative screenshots inspected. All 21 stored keys checked, five generated records reconstructed through published identities; historical generation metadata absent. Package hashes unchanged. All artifacts and reproduction commands are under this evidence directory.\n')
print(json.dumps({'verdict':report['verdict'],'checks':len(report['checks']),'findings':len(report['findings']),'evidence_contract_paths_verified':True,'package_unchanged':True}))
